import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[] times = new String[(int) n];
        for (int i = 0; i < times.length; i++) times[i] = next();

        int[] minutes = new int[(int) n];
        for (int i = 0; i < n; i++) {
            String t = times[i];
            minutes[i] = ((t.charAt(0) - '0') * 10 + (t.charAt(1) - '0')) * 60 + (t.charAt(3) - '0') * 10 + (t.charAt(4) - '0');
        }
        Arrays.sort(minutes);
        int best = minutes[0] + 1440 - minutes[minutes.length - 1];
        for (int i = 1; i < minutes.length; i++) best = Math.min(best, minutes[i] - minutes[i - 1]);
        System.out.println(best);
    }
}
